class FEMenu {
    char data[116];
public:
    virtual ~FEMenu();
};

class FEMenuSystem {
    char data[116];
public:
    FEMenu **menus;
    void *manager;
    int active;
    int size;
    int count;
    void *font;
    virtual ~FEMenuSystem() { delete[] menus; }
};

class FEDebugMenu : public FEMenu {};

class GraphicalMenuSystem : public FEMenuSystem {
    char data[140];
    FEDebugMenu *fedbm;
public:
    enum { BeachMenu = 5 };
    virtual ~GraphicalMenuSystem();
    void killMovie();
};

__asm__(".equ killMovie__19GraphicalMenuSystem, 0x001BE6F0");

GraphicalMenuSystem::~GraphicalMenuSystem()
{
	killMovie();
	delete fedbm;

	// delete all menus except for the map menu
	for(int i=0; i<size; i++)
		if(i != BeachMenu) 
		{
			delete menus[i];
			menus[i] = NULL;
		}
}
